INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000317',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss parliamentarism and democracy theory at B2","Use Parlamentarismus vocabulary","Talk about the Bundestag, representative democracy, and critiques of parliamentarism"],"explanation":{"intro":"Parliamentarism and democracy theory vocabulary covers representative democracy, the Bundestag, and theoretical debates about democratic legitimacy at B2.","culturalNote":"Parlamentarismus und Demokratietheorie: Germany: Grundgesetz (1949) — designed to prevent Weimar''s failure. Key: parlamentarisches System (parliamentary system — government depends on confidence of parliament). Bundestag (709 MPs — 2021 — elections every 4 years — mixed-member proportional). 5%-Klausel (5% threshold — anti-fragmentation). Konstruktives Misstrauensvotum (constructive vote of no confidence — must simultaneously elect successor — Weimar lesson). Bundesrat (upper chamber — 69 votes — state governments). Verfassungsgericht (Constitutional Court — Hüter der Verfassung = guardian of the constitution — based in Karlsruhe). Key theory: Schmitt vs. Kelsen (Carl Schmitt — Weimar — sovereignty/exception — anti-liberal; Hans Kelsen — legal positivism — normative constitution). Repräsentation (representation — mandate theory). Direkte Demokratie (direct democracy — rare in Germany — land referenda — no federal referenda — Weimar trauma). Deliberative Demokratie (Habermas — discourse ethics). Parteienstaat (party state — German democracy = Parteienstaat)."},"examples":[{"german":"Das Grundgesetz hat aus der Weimarer Erfahrung gelernt: Die konstitutionellen Schwachstellen der Weimarer Republik — Direktwahl eines starken Reichspräsidenten, fehlende 5-Prozent-Hürde, kein konstruktives Misstrauensvotum — begünstigten die Erosion der parlamentarischen Demokratie. Das GG begegnet diesen Risiken durch institutionelle Sicherungen, die individuelle Machtzentrierungen erschweren und extreme Parteien vom Parlament fernhalten.","english":"The Basic Law has learned from the Weimar experience: the constitutional weaknesses of the Weimar Republic — direct election of a strong Reich President, no 5-percent threshold, no constructive vote of no confidence — facilitated the erosion of parliamentary democracy. The Basic Law counters these risks through institutional safeguards that make individual concentration of power more difficult and keep extreme parties out of parliament."},{"german":"Die Repräsentation ist das Kernproblem parlamentarischer Demokratie: Wähler delegieren Entscheidungsbefugnis an gewählte Vertreter, die dann für sie entscheiden. Dabei entsteht ein Prinzipal-Agent-Problem: Wie kann sichergestellt werden, dass Vertreter im Interesse der Vertretenen entscheiden, nicht im Interesse von Partei, Lobby oder Eigeninteresse? Verschiedene Demokratietheorien — Delegationstheorie, Mandatstheorie, deliberative Demokratie — geben darauf unterschiedliche Antworten.","english":"Representation is the core problem of parliamentary democracy: voters delegate decision-making authority to elected representatives, who then decide for them. This creates a principal-agent problem: how can it be ensured that representatives decide in the interest of those they represent, not in the interest of party, lobby, or self-interest? Different theories of democracy — delegation theory, mandate theory, deliberative democracy — give different answers to this."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss parliamentary democracy, the Basic Law''s safeguards, and the principal-agent problem of representation at B2."}}',
'{"items":[{"word":"das konstruktive Misstrauensvotum","translation":"constructive vote of no confidence","pronunciation":"dahs kon-STROOK-ti-veh MIS-trow-ens-voh-toom","example":"Konstruktives Misstrauensvotum."},{"word":"die Repräsentation","translation":"representation","pronunciation":"dee reh-prä-zen-ta-TSYOHN","example":"Demokratische Repräsentation."},{"word":"die Erosion","translation":"erosion","pronunciation":"dee eh-ro-ZYOHN","example":"Erosion der Demokratie."},{"word":"begünstigen","translation":"to facilitate/favour","pronunciation":"beh-GÜN-sti-gen","example":"Erosion begünstigen."},{"word":"das Prinzipal-Agent-Problem","translation":"principal-agent problem","pronunciation":"dahs prin-tsi-PAHL-ah-gent-pro-blem","example":"Demokratisches Prinzipal-Agent-Problem."},{"word":"die Entscheidungsbefugnis","translation":"decision-making authority","pronunciation":"dee ent-SHY-doongs-beh-fook-nis","example":"Entscheidungsbefugnis delegieren."}]}',
'{"title":"Etwas begegnet X durch Y — something counters X through Y","pattern":"etwas begegnet X durch Y = something counters X through Y (begegnen + dative = to meet, counter — used when X is a challenge or risk and Y is the institutional/structural response)","explanation":"Begegnen = to meet, encounter, counter (+ dative — begegnet X = meets/counters X). Durch Y = through Y (the means or mechanism of countering). Das GG begegnet diesen Risiken durch institutionelle Sicherungen = the Basic Law counters these risks through institutional safeguards. Used when a designed system, law, or institution deliberately addresses and counters a known risk. Compare: entgegenwirken (to counteract — more active resistance), abmildern (to mitigate — weaker response), vorbeugen (to prevent — more anticipatory), kompensieren (to compensate — post-hoc balancing).","examples":[{"sentence":"Das Unternehmen begegnet Cybersicherheitsrisiken durch mehrschichtige Authentifizierung.","translation":"The company counters cybersecurity risks through multi-layered authentication."},{"sentence":"Das Gesetz begegnet der Machtkonzentration durch Gewaltenteilung.","translation":"The law counters the concentration of power through separation of powers."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Erosion'' means?","options":["erosion","decay","deterioration","decline"],"correctAnswer":"erosion"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Basic Law has learned from the Weimar experience: the constitutional weaknesses of the Weimar Republic — direct election of a strong Reich President, no 5-percent threshold, no constructive vote of no confidence — facilitated the erosion of parliamentary democracy. The Basic Law counters these risks through institutional safeguards that make individual concentration of power more difficult and keep extreme parties out of parliament.","options":["Das Grundgesetz hat aus der Weimarer Erfahrung gelernt: Die konstitutionellen Schwachstellen der Weimarer Republik — Direktwahl eines starken Reichspräsidenten, fehlende 5-Prozent-Hürde, kein konstruktives Misstrauensvotum — begünstigten die Erosion der parlamentarischen Demokratie. Das GG begegnet diesen Risiken durch institutionelle Sicherungen, die individuelle Machtzentrierungen erschweren und extreme Parteien vom Parlament fernhalten.","Das Grundgesetz hat aus dem Scheitern der Weimarer Republik gelernt und Schwachstellen beseitigt.","Die Fünf-Prozent-Hürde und das konstruktive Misstrauensvotum schützen die Demokratie.","Das GG ist eine direkte Reaktion auf die verfassungsrechtlichen Fehler der Weimarer Republik."],"correctAnswer":"Das Grundgesetz hat aus der Weimarer Erfahrung gelernt: Die konstitutionellen Schwachstellen der Weimarer Republik — Direktwahl eines starken Reichspräsidenten, fehlende 5-Prozent-Hürde, kein konstruktives Misstrauensvotum — begünstigten die Erosion der parlamentarischen Demokratie. Das GG begegnet diesen Risiken durch institutionelle Sicherungen, die individuelle Machtzentrierungen erschweren und extreme Parteien vom Parlament fernhalten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gesetz begegnet der Machtkonzentration durch ___.","options":["Gewaltenteilung","Kontrolle","Aufsicht","Regulierung"],"correctAnswer":"Gewaltenteilung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The company counters cybersecurity risks through multi-layered authentication","wordBankItems":["Das","Unternehmen","begegnet","Cybersicherheitsrisiken","durch","mehrschichtige","Authentifizierung","."],"correctAnswer":"Das Unternehmen begegnet Cybersicherheitsrisiken durch mehrschichtige Authentifizierung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Begünstigen'' means?","options":["to facilitate/favour","to enable","to support","to promote"],"correctAnswer":"to facilitate/favour"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000318',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss constitutional law and the Basic Law at B2","Use Verfassungsrecht vocabulary","Talk about Germany''s Basic Law, the Constitutional Court, and constitutional democracy"],"explanation":{"intro":"Constitutional law vocabulary covers the Basic Law, the Constitutional Court, and Germany''s constitutional democracy at B2.","culturalNote":"Verfassungsrecht und Grundgesetz: Germany: Grundgesetz (Basic Law — 1949 — not ''Verfassung'' because originally seen as provisional — reunification 1990 maintained GG). Key articles: Art. 1 (Menschenwürde — human dignity — inviolable), Art. 2 (Persönlichkeitsrecht — right to personality), Art. 3 (Gleichheit — equality), Art. 20 (Sozialstaat, Demokratie, Föderalismus, Rechtsstaat), Art. 79 III (Ewigkeitsklausel — eternity clause — certain provisions cannot be amended). Bundesverfassungsgericht (BVerfG — Karlsruhe — most trusted German institution — 16 judges — 2 senates). Key rulings: Maastricht (1993), Lissabon (2009), Klimaschutz (2021), Wahlrecht (2023). Normenkontrolle (judicial review). Verfassungsbeschwerde (constitutional complaint — 6000/year — 97% rejected). Ewigkeitsklausel: Art. 1 and 20 cannot be amended even by 2/3 majority. Key concept: Rechtsstaat (rule of law — different from Rechtstaat — German specific — law as bulwark against arbitrary power)."},"examples":[{"german":"Die Ewigkeitsklausel des Grundgesetzes (Art. 79 Abs. 3) markiert die äußerste Grenze demokratischer Mehrheitsentscheidungen: Selbst eine verfassungsändernde Zweidrittelmehrheit kann die in Art. 1 (Menschenwürde) und Art. 20 (Staatsstrukturprinzipien) verankerten Grundnormen nicht antasten — eine Normhierarchie, die bestimmte Verfassungsprinzipien dem demokratischen Mehrheitsprinzip entzieht und sie als unveräußerlichen Kern konstitutioneller Demokratie schützt.","english":"The eternity clause of the Basic Law (Art. 79 para. 3) marks the outermost limit of democratic majority decisions: even a constitution-amending two-thirds majority cannot touch the basic norms anchored in Art. 1 (human dignity) and Art. 20 (state structure principles) — a norm hierarchy that withdraws certain constitutional principles from the democratic majority principle and protects them as the inalienable core of constitutional democracy."},{"german":"Das Bundesverfassungsgericht hat eine einzigartige Stellung im deutschen politischen System: Als Hüter der Verfassung kontrolliert es, ob Gesetze und staatliches Handeln mit dem Grundgesetz vereinbar sind — und es ist das am meisten vertraute staatliche Institution in Deutschland. Diese Vertrauensstellung setzt voraus, dass das Gericht als überparteiliche, rechtlich gebundene Instanz wahrgenommen wird, nicht als politischer Akteur.","english":"The Federal Constitutional Court has a unique position in the German political system: as guardian of the constitution, it controls whether laws and state action are compatible with the Basic Law — and it is the most trusted state institution in Germany. This position of trust presupposes that the court is perceived as a non-partisan, legally bound authority, not as a political actor."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Basic Law''s eternity clause, the Constitutional Court, and constitutional democracy at B2."}}',
'{"items":[{"word":"die Ewigkeitsklausel","translation":"eternity clause","pronunciation":"dee EH-vikh-kyts-klow-zel","example":"Ewigkeitsklausel des GG."},{"word":"die Normhierarchie","translation":"norm hierarchy","pronunciation":"dee NORM-hee-er-ar-khee","example":"Verfassungsrechtliche Normhierarchie."},{"word":"unveräußerlich","translation":"inalienable","pronunciation":"oon-fer-OY-ser-likh","example":"Unveräußerlicher Kern."},{"word":"der Hüter","translation":"guardian","pronunciation":"dayr HÜ-ter","example":"Hüter der Verfassung."},{"word":"überparteilich","translation":"non-partisan","pronunciation":"ü-ber-par-TY-likh","example":"Überparteiliche Instanz."},{"word":"antasten","translation":"to touch/violate","pronunciation":"AN-tas-ten","example":"Grundrechte antasten."}]}',
'{"title":"Etwas entzieht X dem Y-Prinzip — something withdraws X from the Y-principle","pattern":"etwas entzieht X dem Y-Prinzip = something withdraws X from the Y-principle (entziehen + dative = to withdraw from, remove from; marks that X is taken out of the jurisdiction of a principle, removing it from a domain of application)","explanation":"Entziehen = to withdraw, remove from (separable: entzieht...X — takes X away from something). Dem Y-Prinzip = from the Y-principle (dative — the principle from which X is withdrawn). Eine Normhierarchie entzieht bestimmte Prinzipien dem demokratischen Mehrheitsprinzip = a norm hierarchy withdraws certain principles from the democratic majority principle. Used when a higher-order rule removes something from the reach of a lower-order rule or principle. Compare: sich der X entziehen (to evade X — more agency-based), außerhalb von X stellen (to place outside of X — more positional), schützen vor X (to protect from X — more defensive), immunisieren gegen X (to immunise against X — more resistant framing).","examples":[{"sentence":"Das Datenschutzgesetz entzieht bestimmte Daten dem kommerziellen Zugriff.","translation":"The data protection law withdraws certain data from commercial access."},{"sentence":"Grundrechte entziehen bestimmte Freiheiten dem staatlichen Eingriff.","translation":"Fundamental rights withdraw certain freedoms from state interference."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unveräußerlich'' means?","options":["inalienable","untouchable","inviolable","immutable"],"correctAnswer":"inalienable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The eternity clause of the Basic Law (Art. 79 para. 3) marks the outermost limit of democratic majority decisions: even a constitution-amending two-thirds majority cannot touch the basic norms anchored in Art. 1 (human dignity) and Art. 20 (state structure principles) — a norm hierarchy that withdraws certain constitutional principles from the democratic majority principle and protects them as the inalienable core of constitutional democracy.","options":["Die Ewigkeitsklausel des Grundgesetzes (Art. 79 Abs. 3) markiert die äußerste Grenze demokratischer Mehrheitsentscheidungen: Selbst eine verfassungsändernde Zweidrittelmehrheit kann die in Art. 1 (Menschenwürde) und Art. 20 (Staatsstrukturprinzipien) verankerten Grundnormen nicht antasten — eine Normhierarchie, die bestimmte Verfassungsprinzipien dem demokratischen Mehrheitsprinzip entzieht und sie als unveräußerlichen Kern konstitutioneller Demokratie schützt.","Die Ewigkeitsklausel bedeutet, dass einige Artikel des GG niemals geändert werden können.","Art. 1 und Art. 20 GG sind absolut geschützt — auch gegen eine Zwei-Drittel-Mehrheit.","Das GG schützt Menschenwürde und Demokratie vor dem eigenen Mehrheitsprinzip."],"correctAnswer":"Die Ewigkeitsklausel des Grundgesetzes (Art. 79 Abs. 3) markiert die äußerste Grenze demokratischer Mehrheitsentscheidungen: Selbst eine verfassungsändernde Zweidrittelmehrheit kann die in Art. 1 (Menschenwürde) und Art. 20 (Staatsstrukturprinzipien) verankerten Grundnormen nicht antasten — eine Normhierarchie, die bestimmte Verfassungsprinzipien dem demokratischen Mehrheitsprinzip entzieht und sie als unveräußerlichen Kern konstitutioneller Demokratie schützt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Grundrechte entziehen bestimmte Freiheiten dem staatlichen ___.","options":["Eingriff","Zugriff","Einfluss","Einschränkung"],"correctAnswer":"Eingriff"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The data protection law withdraws certain data from commercial access","wordBankItems":["Das","Datenschutzgesetz","entzieht","bestimmte","Daten","dem","kommerziellen","Zugriff","."],"correctAnswer":"Das Datenschutzgesetz entzieht bestimmte Daten dem kommerziellen Zugriff ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Antasten'' means?","options":["to touch/violate","to challenge","to undermine","to attack"],"correctAnswer":"to touch/violate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000319',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss federalism and state policy at B2","Use Föderalismus vocabulary","Talk about Germany''s federal structure, Länderfinanzausgleich, and cooperation federalism"],"explanation":{"intro":"Federalism vocabulary covers Germany''s two-level federal structure, the Länderfinanzausgleich (fiscal equalisation), and cooperation federalism at B2.","culturalNote":"Föderalismus und Länderpolitik: Germany: 16 Länder (states — 3 city-states: Berlin, Hamburg, Bremen; largest: NRW 18M; smallest: Bremen 680,000). Key: Bundesrat (upper chamber — state governments — 69 votes weighted by population). Gemeinschaftsaufgaben (joint tasks — Art. 91 GG — federal and state cooperation). Länderfinanzausgleich (fiscal equalisation — richer states transfer to poorer states — Bayern, Baden-Württemberg, Hessen vs. Berlin, Brandenburg, Bremen). Bildungsföderalismus (education federalism — problematic: 16 different systems). Unitarisierungstendenzen (unitarisation tendencies — increasing centralization). Key: Konkurrenzföderalismus vs. Kooperationsföderalismus (competitive vs. cooperative federalism). Polit-Blockade (political blockade — Bundesrat blocking Bundestag legislation — reform 2006 reduced this). Gemeindeordnungen (municipal codes). Kommunale Selbstverwaltung (municipal self-government — Art. 28 GG). Subsidiaritätsprinzip (subsidiarity)."},"examples":[{"german":"Der Länderfinanzausgleich ist ein Solidaritätsmechanismus, der den unitarischen Impuls des deutschen Föderalismus zeigt: Statt finanzielle Unterschiede zwischen reichen und armen Ländern durch Wettbewerb zu lösen, transferiert der horizontale Finanzausgleich Mittel von starken (Bayern, Hessen) zu schwachen Ländern (Berlin, Bremen) — ein Prinzip, das Mindestversorgung sichert, aber Anreize zum Steuererhöhen reduziert.","english":"The fiscal equalisation scheme is a solidarity mechanism that shows the unitarian impulse of German federalism: instead of resolving financial differences between rich and poor states through competition, the horizontal fiscal equalisation transfers resources from strong (Bavaria, Hesse) to weak states (Berlin, Bremen) — a principle that secures a minimum provision, but reduces incentives to increase taxes."},{"german":"Bildungsföderalismus offenbart die Grenzen der Länderkompetenz: 16 unterschiedliche Schulsysteme, inkompatible Schulabschlüsse und heterogene Unterrichtsinhalte erschweren Mobilität und nationale Vergleichbarkeit — Probleme, die der Bund nicht lösen darf, weil Bildung Ländersache ist. Die KMK versucht, durch Koordination Mindeststandards zu setzen, ohne die Ländersouveränität formell anzutasten — ein Muster für die strukturellen Grenzen freiwilliger Koordination im Föderalismus.","english":"Education federalism reveals the limits of state competence: 16 different school systems, incompatible school qualifications, and heterogeneous teaching contents make mobility and national comparability difficult — problems that the federal government is not permitted to solve, because education is a state matter. The Standing Conference of Education Ministers attempts to set minimum standards through coordination, without formally touching state sovereignty — a pattern for the structural limits of voluntary coordination in federalism."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Länderfinanzausgleich, education federalism, and the limits of voluntary coordination at B2."}}',
'{"items":[{"word":"der Länderfinanzausgleich","translation":"fiscal equalisation scheme","pronunciation":"dayr LEN-der-fi-NANTS-ows-glykh","example":"Horizontaler Länderfinanzausgleich."},{"word":"unitarisch","translation":"unitarian","pronunciation":"oo-ni-TAH-rish","example":"Unitarische Tendenzen."},{"word":"die Ländersouveränität","translation":"state sovereignty","pronunciation":"dee LEN-der-zoo-veh-rä-ni-TÄT","example":"Ländersouveränität wahren."},{"word":"freiwillig","translation":"voluntary","pronunciation":"FRY-vil-ikh","example":"Freiwillige Koordination."},{"word":"heterogen","translation":"heterogeneous","pronunciation":"heh-teh-ro-GEHN","example":"Heterogene Inhalte."},{"word":"das Anreiz","translation":"incentive","pronunciation":"dahs AN-ryts","example":"Finanzielle Anreize."}]}',
'{"title":"X offenbart die Grenzen von Y — X reveals the limits of Y","pattern":"X offenbart die Grenzen von Y = X reveals the limits of Y (offenbaren = to reveal; Grenzen = limits, boundaries; von Y = of Y — marks that X is a case or phenomenon that shows where Y reaches its limits or breaks down)","explanation":"Offenbaren = to reveal (offenbar = obvious; offenbaren = to make obvious, reveal). Die Grenzen von Y = the limits of Y (where Y can no longer function, is insufficient, or runs into structural constraints). Bildungsföderalismus offenbart die Grenzen der Länderkompetenz = education federalism reveals the limits of state competence. The pattern is used when a specific example or phenomenon makes the structural limitations of a larger system visible. Compare: zeigt die Grenzen von (shows the limits of — more neutral), bringt die Grenzen zum Vorschein (brings the limits to the fore — similar, more emergence), stößt an die Grenzen von (comes up against the limits of — more dynamic, hitting the wall), verdeutlicht die Schwächen von (clarifies the weaknesses of — more evaluative).","examples":[{"sentence":"Der Reformversuch offenbart die Grenzen eines konsensorientierten Systems.","translation":"The reform attempt reveals the limits of a consensus-oriented system."},{"sentence":"Die Pandemie hat die Grenzen nationaler Gesundheitssysteme offenbart.","translation":"The pandemic revealed the limits of national health systems."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unitarisch'' means?","options":["unitarian","centralised","uniform","unified"],"correctAnswer":"unitarian"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The fiscal equalisation scheme is a solidarity mechanism that shows the unitarian impulse of German federalism: instead of resolving financial differences between rich and poor states through competition, the horizontal fiscal equalisation transfers resources from strong (Bavaria, Hesse) to weak states (Berlin, Bremen) — a principle that secures a minimum provision, but reduces incentives to increase taxes.","options":["Der Länderfinanzausgleich ist ein Solidaritätsmechanismus, der den unitarischen Impuls des deutschen Föderalismus zeigt: Statt finanzielle Unterschiede zwischen reichen und armen Ländern durch Wettbewerb zu lösen, transferiert der horizontale Finanzausgleich Mittel von starken (Bayern, Hessen) zu schwachen Ländern (Berlin, Bremen) — ein Prinzip, das Mindestversorgung sichert, aber Anreize zum Steuererhöhen reduziert.","Reiche Länder wie Bayern zahlen in den Länderfinanzausgleich ein, arme Länder bekommen heraus.","Der Finanzausgleich ist eine Form von Solidarität — er reduziert aber Anreize für Eigeninitiative.","Bayern und Hessen finanzieren Bremen und Berlin — das ist das Solidaritätsprinzip des Föderalismus."],"correctAnswer":"Der Länderfinanzausgleich ist ein Solidaritätsmechanismus, der den unitarischen Impuls des deutschen Föderalismus zeigt: Statt finanzielle Unterschiede zwischen reichen und armen Ländern durch Wettbewerb zu lösen, transferiert der horizontale Finanzausgleich Mittel von starken (Bayern, Hessen) zu schwachen Ländern (Berlin, Bremen) — ein Prinzip, das Mindestversorgung sichert, aber Anreize zum Steuererhöhen reduziert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Pandemie hat die Grenzen nationaler Gesundheitssysteme ___.","options":["offenbart","gezeigt","enthüllt","verdeutlicht"],"correctAnswer":"offenbart"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The reform attempt reveals the limits of a consensus-oriented system","wordBankItems":["Der","Reformversuch","offenbart","die","Grenzen","eines","konsensorientierten","Systems","."],"correctAnswer":"Der Reformversuch offenbart die Grenzen eines konsensorientierten Systems ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Anreiz'' means?","options":["incentive","motive","stimulus","reward"],"correctAnswer":"incentive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000031a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss European integration at B2","Use Europäische Integration vocabulary","Talk about EU history, Germany''s European role, and EU reform debates"],"explanation":{"intro":"European integration vocabulary covers the EU''s history, Germany''s European commitment, and debates about EU reform at B2.","culturalNote":"Europäische Integration: Germany: Nie wieder Krieg (never again war — European integration as peace project — Konrad Adenauer, Robert Schuman, Jean Monnet). ECSC 1951 → EEC 1957 → EU 1992 → Eurozone 1999 → Lisbon Treaty 2007. Key: Deutschland als Europas Mittelmacht — Gerhard Schröder, Angela Merkel, Olaf Scholz. Key: Europäische Verfassungsvertrag (2005 — rejected by France and Netherlands — replaced by Lisbon). Eurokrise (2010-2015 — Greece — Merkel''s austerity — Schäuble). Key: Söhne Europas vs. Europaskeptiker (pro-EU vs. Euro-sceptic). Schengen (freedom of movement — exceptions during COVID). EU enlargement (Osterweiterung 2004). Subsidiarity. Democratic deficit. Commission, Parliament, Council. ECJ (Court of Justice). Bundesverfassungsgericht and EU law (ultra vires debate). Key Germany: Verfassungsidentität (constitutional identity) limits of EU primacy."},"examples":[{"german":"Die europäische Integration ist das ehrgeizigste Friedensprojekt der Nachkriegsgeschichte: Indem es den Kern des Nationalstaats — die Wirtschaft und zunehmend Recht, Währung, Außenhandel — in supranationale Institutionen eingebettet hat, hat es Krieg zwischen den Gründungsstaaten strukturell unwahrscheinlich gemacht. Deutschland ist in dieser Ordnung sowohl der größte Nutznießer als auch der zentrale Architektur — eine Doppelrolle, die besonderes Gewicht mitbringt.","english":"European integration is the most ambitious peace project in postwar history: by embedding the core of the nation-state — the economy and increasingly law, currency, foreign trade — in supranational institutions, it has made war between the founding states structurally improbable. Germany is in this order both the greatest beneficiary and the central architect — a dual role that carries particular weight."},{"german":"Das demokratische Defizit der EU bezeichnet eine strukturelle Legitimitätslücke: Europäische Institutionen — Kommission, Rat — treffen weitreichende Entscheidungen mit schwacher demokratischer Rückkoppelung. Das Europäische Parlament hat an Gewicht gewonnen, aber die Öffentlichkeit ist schwach — ein europäischer Demos, der die Legitimitätsbasis transnationaler Demokratie bilden würde, fehlt weitgehend. Dieses Problem ist nicht durch institutionelle Reformen allein lösbar.","english":"The democratic deficit of the EU designates a structural legitimacy gap: European institutions — Commission, Council — make far-reaching decisions with weak democratic feedback. The European Parliament has gained weight, but the public sphere is weak — a European demos that would form the legitimacy basis of transnational democracy is largely absent. This problem cannot be solved by institutional reforms alone."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss EU integration, the democratic deficit, and Germany''s dual role as beneficiary and architect at B2."}}',
'{"items":[{"word":"supranational","translation":"supranational","pronunciation":"zoo-pra-na-tsyo-NAHL","example":"Supranationale Institutionen."},{"word":"das demokratische Defizit","translation":"democratic deficit","pronunciation":"dahs deh-mo-KRA-tish-eh deh-fi-TSEET","example":"Demokratisches Defizit der EU."},{"word":"der Demos","translation":"demos/people","pronunciation":"dayr DEH-mos","example":"Europäischer Demos."},{"word":"der Nutznießer","translation":"beneficiary","pronunciation":"dayr NOOTS-nee-ser","example":"Größter Nutznießer."},{"word":"die Rückkoppelung","translation":"feedback","pronunciation":"dee RÜK-ko-pel-oong","example":"Demokratische Rückkoppelung."},{"word":"weitreichend","translation":"far-reaching","pronunciation":"VYT-ry-khend","example":"Weitreichende Entscheidungen."}]}',
'{"title":"X ist nicht durch Y allein lösbar — X cannot be solved by Y alone","pattern":"X ist nicht durch Y allein lösbar = X cannot be solved by Y alone (lösbar = solvable — adjective; durch Y allein = through Y alone; marks that Y is insufficient and additional elements are needed)","explanation":"Lösbar = solvable (lösen = to solve; -bar = able to be — similar to -able in English; das Problem ist lösbar = the problem is solvable). Nicht durch Y allein lösbar = not solvable through Y alone (nicht + durch + allein + lösbar = negative + instrument + exclusivity + solvability). Das Problem ist nicht durch institutionelle Reformen allein lösbar = the problem cannot be solved by institutional reforms alone. Marks insufficiency of a single approach — more is needed. Compare: X erfordert mehr als Y (X requires more than Y — positive framing of what''s missing), Y greift zu kurz (Y falls short — more dismissive), Y allein reicht nicht aus (Y alone is not sufficient — direct statement of insufficiency), über Y hinausgehen müssen (must go beyond Y).","examples":[{"sentence":"Klimawandel ist nicht durch technische Lösungen allein lösbar.","translation":"Climate change cannot be solved by technical solutions alone."},{"sentence":"Armut ist nicht durch Wirtschaftswachstum allein lösbar.","translation":"Poverty cannot be solved by economic growth alone."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Supranational'' means?","options":["supranational","transnational","international","multinational"],"correctAnswer":"supranational"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The democratic deficit of the EU designates a structural legitimacy gap: European institutions — Commission, Council — make far-reaching decisions with weak democratic feedback. The European Parliament has gained weight, but the public sphere is weak — a European demos that would form the legitimacy basis of transnational democracy is largely absent. This problem cannot be solved by institutional reforms alone.","options":["Das demokratische Defizit der EU bezeichnet eine strukturelle Legitimitätslücke: Europäische Institutionen — Kommission, Rat — treffen weitreichende Entscheidungen mit schwacher demokratischer Rückkoppelung. Das Europäische Parlament hat an Gewicht gewonnen, aber die Öffentlichkeit ist schwach — ein europäischer Demos, der die Legitimitätsbasis transnationaler Demokratie bilden würde, fehlt weitgehend. Dieses Problem ist nicht durch institutionelle Reformen allein lösbar.","Das EU-Parlament hat zu wenig Macht — das erzeugt ein demokratisches Defizit.","Ohne einen europäischen Demos fehlt der EU die demokratische Legitimation.","Institutionelle Reformen können das demokratische Defizit der EU nicht alleine lösen."],"correctAnswer":"Das demokratische Defizit der EU bezeichnet eine strukturelle Legitimitätslücke: Europäische Institutionen — Kommission, Rat — treffen weitreichende Entscheidungen mit schwacher demokratischer Rückkoppelung. Das Europäische Parlament hat an Gewicht gewonnen, aber die Öffentlichkeit ist schwach — ein europäischer Demos, der die Legitimitätsbasis transnationaler Demokratie bilden würde, fehlt weitgehend. Dieses Problem ist nicht durch institutionelle Reformen allein lösbar."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Klimawandel ist nicht durch technische Lösungen allein ___.","options":["lösbar","löslich","lösend","gelöst"],"correctAnswer":"lösbar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Poverty cannot be solved by economic growth alone","wordBankItems":["Armut","ist","nicht","durch","Wirtschaftswachstum","allein","lösbar","."],"correctAnswer":"Armut ist nicht durch Wirtschaftswachstum allein lösbar ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Nutznießer'' means?","options":["beneficiary","profiteer","recipient","winner"],"correctAnswer":"beneficiary"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000031b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss foreign policy and diplomacy at B2","Use Außenpolitik vocabulary","Talk about Germany''s foreign policy tradition, Zeitenwende, and Wandel durch Handel"],"explanation":{"intro":"Foreign policy vocabulary covers Germany''s foreign policy tradition, Wandel durch Handel (change through trade), and Zeitenwende (turning point) at B2.","culturalNote":"Außenpolitik und Diplomatie: Germany: Zivilmacht (civilian power tradition — Hans Maull — restraint, multilateralism, economic engagement). Wandel durch Handel (change through trade — Egon Bahr Ostpolitik 1963 — engagement with East Germany/USSR — modernised as approach to Russia and China). Zeitenwende (turning point — Olaf Scholz February 2022 — after Russia invaded Ukraine — new era of German foreign policy — defence spending increase). Key: 2% NATO target (long resisted — now committed). Sondervermögen Bundeswehr (€100bn special fund for defence 2022). Nordstream (gas pipeline — Russia — Germany — controversial — sabotaged 2022). China policy: Entkoppelung vs. Einbindung (decoupling vs. engagement). Key: auswärtiges Amt (Foreign Ministry). Auswärtige Kulturpolitik (Goethe Institut, DAAD). Key: Rüstungsexporte (arms exports — controversial — Saudi Arabia). Multilateralismus (multilateralism — German tradition)."},"examples":[{"german":"Die Zeitenwende markiert einen paradigmatischen Bruch mit der deutschen Außenpolitikstradition der Nachkriegszeit: Das Konzept der Zivilmacht — Verzicht auf Machtpolitik, Multilateralismus, wirtschaftliche Einbindung als Friedensstrategie — wurde von der Annahme getragen, dass Wandel durch Handel Regime moderat macht. Russlands Angriffskrieg auf die Ukraine hat diese Prämisse fundamental erschüttert und eine strategische Neubewertung erzwungen.","english":"The Zeitenwende marks a paradigmatic break with the German foreign policy tradition of the postwar era: the concept of civilian power — renunciation of power politics, multilateralism, economic engagement as peace strategy — was sustained by the assumption that change through trade moderates regimes. Russia''s war of aggression against Ukraine has fundamentally shaken this premise and forced a strategic reassessment."},{"german":"Die deutsche Abhängigkeit von russischem Gas war eine strategische Verwundbarkeit, die über Jahrzehnte nicht als solche wahrgenommen wurde: Wirtschaftliche Interdependenz galt als friedensstabilisierend — der Glaube, dass Handelsbeziehungen Kriege verhindern (Montesquieu: ''doux commerce''). Nordstream 2 wurde als wirtschaftliches Projekt verteidigt und seine geopolitischen Implikationen wurden systematisch unterschätzt.","english":"Germany''s dependence on Russian gas was a strategic vulnerability that was not perceived as such for decades: economic interdependence was regarded as peace-stabilising — the belief that trade relationships prevent wars (Montesquieu: ''doux commerce''). Nord Stream 2 was defended as an economic project and its geopolitical implications were systematically underestimated."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Zeitenwende, Wandel durch Handel, and the reassessment of Russian gas dependency at B2."}}',
'{"items":[{"word":"die Zivilmacht","translation":"civilian power","pronunciation":"dee tsi-FEEL-makht","example":"Deutschland als Zivilmacht."},{"word":"der Paradigmenwechsel","translation":"paradigm shift","pronunciation":"dayr pa-ra-DIG-men-vek-sel","example":"Außenpolitischer Paradigmenwechsel."},{"word":"erschüttern","translation":"to shake/shatter","pronunciation":"er-SHÜT-tern","example":"Prämissen erschüttern."},{"word":"die Verwundbarkeit","translation":"vulnerability","pronunciation":"dee fer-VOOND-bar-kyt","example":"Strategische Verwundbarkeit."},{"word":"unterschätzen","translation":"to underestimate","pronunciation":"oon-ter-SHETS-en","example":"Implikationen unterschätzen."},{"word":"erzwingen","translation":"to force/compel","pronunciation":"er-TSVING-en","example":"Neubewertung erzwingen."}]}',
'{"title":"X wurde von der Annahme getragen, dass Y — X was sustained by the assumption that Y","pattern":"X wurde von der Annahme getragen, dass Y = X was sustained by the assumption that Y (getragen von = sustained by, carried by — passive; Annahme = assumption; marks the underlying assumption that kept X viable)","explanation":"Getragen von = sustained by, carried by (tragen = to carry; passive: wird von X getragen = is carried by X). Annahme = assumption (what is taken to be true without proof). X wurde von der Annahme getragen, dass Y = X was sustained by the assumption that Y was true. The pattern reveals the hidden assumption that kept a policy, theory, or practice running — particularly useful when that assumption turned out to be wrong. Compare: basierte auf der Annahme (was based on the assumption — similar, less dynamic), ruhte auf der Prämisse (rested on the premise — more static), setzte voraus, dass (presupposed that — logical precondition), funktionierte solange (worked as long as — more conditional framing).","examples":[{"sentence":"Das System wurde von der Annahme getragen, dass alle Akteure rational handeln.","translation":"The system was sustained by the assumption that all actors act rationally."},{"sentence":"Die Strategie wurde von der Annahme getragen, dass der Markt sich selbst korrigiert.","translation":"The strategy was sustained by the assumption that the market corrects itself."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erschüttern'' means?","options":["to shake/shatter","to disturb","to undermine","to challenge"],"correctAnswer":"to shake/shatter"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Zeitenwende marks a paradigmatic break with the German foreign policy tradition of the postwar era: the concept of civilian power — renunciation of power politics, multilateralism, economic engagement as peace strategy — was sustained by the assumption that change through trade moderates regimes. Russia''s war of aggression against Ukraine has fundamentally shaken this premise and forced a strategic reassessment.","options":["Die Zeitenwende markiert einen paradigmatischen Bruch mit der deutschen Außenpolitikstradition der Nachkriegszeit: Das Konzept der Zivilmacht — Verzicht auf Machtpolitik, Multilateralismus, wirtschaftliche Einbindung als Friedensstrategie — wurde von der Annahme getragen, dass Wandel durch Handel Regime moderat macht. Russlands Angriffskrieg auf die Ukraine hat diese Prämisse fundamental erschüttert und eine strategische Neubewertung erzwungen.","Die Zeitenwende ist Deutschlands Reaktion auf Russlands Invasion der Ukraine.","Wandel durch Handel hat versagt — Deutschland muss seine Außenpolitik neu ausrichten.","Olaf Scholz hat 2022 einen Wendepunkt in der deutschen Außenpolitik angekündigt."],"correctAnswer":"Die Zeitenwende markiert einen paradigmatischen Bruch mit der deutschen Außenpolitikstradition der Nachkriegszeit: Das Konzept der Zivilmacht — Verzicht auf Machtpolitik, Multilateralismus, wirtschaftliche Einbindung als Friedensstrategie — wurde von der Annahme getragen, dass Wandel durch Handel Regime moderat macht. Russlands Angriffskrieg auf die Ukraine hat diese Prämisse fundamental erschüttert und eine strategische Neubewertung erzwungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das System wurde von der Annahme getragen, dass alle Akteure rational ___.","options":["handeln","sind","agieren","entscheiden"],"correctAnswer":"handeln"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The strategy was sustained by the assumption that the market corrects itself","wordBankItems":["Die","Strategie","wurde","von","der","Annahme","getragen",",","dass","der","Markt","sich","selbst","korrigiert","."],"correctAnswer":"Die Strategie wurde von der Annahme getragen , dass der Markt sich selbst korrigiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verwundbarkeit'' means?","options":["vulnerability","weakness","fragility","susceptibility"],"correctAnswer":"vulnerability"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000031c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss security policy and defence at B2","Use Sicherheitspolitik vocabulary","Talk about Germany''s Bundeswehr, NATO, and the debate over rearmament"],"explanation":{"intro":"Security policy vocabulary covers NATO, Bundeswehr reform, Germany''s 2% target, and the debate over the Zeitenwende at B2.","culturalNote":"Sicherheitspolitik und Verteidigung: Germany: Bundeswehr (250,000 personnel — underequipped for years). NATO (Article 5 — collective defence). 2% GDP defence commitment — Germany chronically below (1.4% 2022 — committed 2% post-Zeitenwende). Sondervermögen (€100bn special fund 2022 — approved by Bundestag). Wehrpflicht (conscription — suspended 2011 — debate about reintroduction). Key: Landes- und Bündnisverteidigung (territorial and alliance defence — back after Ukraine). Rüstungsexporte (arms exports — Saudi Arabia, Ukraine). Doppelte Staatsbürgerschaft für Bundeswehr (non-EU recruitment 2024). NATOs Ostflanke (eastern flank — Baltic States, Poland — German brigade in Lithuania). Key tension: Kriegstüchtigkeit (readiness for war — Boris Pistorius — controversial term in Germany''s post-1945 culture). Peacekeeping vs. warfighting. Key: Neue Verteidigungsdebatte (rearmament debate — historic shift after 2022)."},"examples":[{"german":"Deutschlands langes Zögern beim NATO-2%-Ziel spiegelt einen fundamentalen kulturellen Widerspruch wider: Die Nachkriegskultur des Landes ist tief antimilitaristisch geprägt — durch die NS-Vergangenheit, durch die Friedensbewegung der 1980er und durch die Überzeugung, dass wirtschaftliche Einbindung sicherer ist als Rüstung. Die Zeitenwende hat diesen kulturellen Grundkonsens unter Druck gesetzt, aber nicht aufgelöst.","english":"Germany''s long hesitation over the NATO 2% target reflects a fundamental cultural contradiction: the country''s postwar culture is deeply stamped with anti-militarism — through the Nazi past, through the peace movement of the 1980s, and through the conviction that economic engagement is safer than rearmament. The Zeitenwende has put this cultural basic consensus under pressure, but has not dissolved it."},{"german":"Kollektive Verteidigung im NATO-Rahmen illustriert das Problem der Glaubwürdigkeit in der Abschreckung: Artikel 5 verpflichtet alle NATO-Mitglieder, ein angegriffenes Mitglied zu verteidigen — aber die Glaubwürdigkeit dieser Verpflichtung hängt von der wahrgenommenen Bereitschaft ab, tatsächlich Truppen einzusetzen. Wenn diese Bereitschaft bezweifelt wird — wie in der Debatte über US-Engagement unter Trump — wird Abschreckung geschwächt.","english":"Collective defence in the NATO framework illustrates the problem of credibility in deterrence: Article 5 obliges all NATO members to defend an attacked member — but the credibility of this obligation depends on the perceived willingness to actually deploy troops. When this willingness is doubted — as in the debate about US engagement under Trump — deterrence is weakened."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s NATO 2% commitment, the Zeitenwende cultural debate, and deterrence credibility at B2."}}',
'{"items":[{"word":"das Zögern","translation":"hesitation","pronunciation":"dahs TSÖH-gern","example":"Deutschlands Zögern."},{"word":"antimilitaristisch","translation":"anti-militarist","pronunciation":"AN-ti-mi-li-ta-RIS-tish","example":"Antimilitaristische Kultur."},{"word":"die Glaubwürdigkeit","translation":"credibility","pronunciation":"dee GLOW-würr-dikh-kyt","example":"Glaubwürdigkeit der Abschreckung."},{"word":"die Abschreckung","translation":"deterrence","pronunciation":"dee AB-shrek-oong","example":"Nukleare Abschreckung."},{"word":"geprägt","translation":"stamped/shaped","pronunciation":"geh-PRÄKT","example":"Von der Geschichte geprägt."},{"word":"kollektiv","translation":"collective","pronunciation":"ko-LEK-teef","example":"Kollektive Verteidigung."}]}',
'{"title":"X steht Y unter Druck, aber löst Y nicht auf — X puts Y under pressure but does not dissolve Y","pattern":"X setzt Y unter Druck, aber löst Y nicht auf = X puts Y under pressure, but does not dissolve Y (unter Druck setzen = to put under pressure; auflösen = to dissolve, resolve — the contrast marks a partial but incomplete transformation)","explanation":"Unter Druck setzen = to put under pressure (Druck = pressure; setzen = to place; unter Druck = under pressure). Auflösen = to dissolve (lösen = to solve; auf = open/apart — auflösen = to dissolve, undo). Die Zeitenwende setzt den Grundkonsens unter Druck, aber löst ihn nicht auf = the Zeitenwende puts the basic consensus under pressure, but does not dissolve it. Marks partial, incomplete change: the pressure is real, but the old structure/value persists. Compare: erschüttern (to shake — stronger, more violent), in Frage stellen (to call into question — more analytical), aushöhlen (to hollow out — gradual degradation), überwinden (to overcome — complete dissolution).","examples":[{"sentence":"Die neue Konkurrenz setzt das Geschäftsmodell unter Druck, löst es aber nicht auf.","translation":"The new competition puts the business model under pressure, but does not dissolve it."},{"sentence":"Die Finanzkrise hat den Konsens unter Druck gesetzt, aber nicht aufgelöst.","translation":"The financial crisis put the consensus under pressure, but did not dissolve it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abschreckung'' means?","options":["deterrence","deterrent","dissuasion","threat"],"correctAnswer":"deterrence"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s long hesitation over the NATO 2% target reflects a fundamental cultural contradiction: the country''s postwar culture is deeply stamped with anti-militarism — through the Nazi past, through the peace movement of the 1980s, and through the conviction that economic engagement is safer than rearmament. The Zeitenwende has put this cultural basic consensus under pressure, but has not dissolved it.","options":["Deutschlands langes Zögern beim NATO-2%-Ziel spiegelt einen fundamentalen kulturellen Widerspruch wider: Die Nachkriegskultur des Landes ist tief antimilitaristisch geprägt — durch die NS-Vergangenheit, durch die Friedensbewegung der 1980er und durch die Überzeugung, dass wirtschaftliche Einbindung sicherer ist als Rüstung. Die Zeitenwende hat diesen kulturellen Grundkonsens unter Druck gesetzt, aber nicht aufgelöst.","Deutschland zögert mit dem NATO-Ziel, weil es kulturell antimilitaristisch ist.","Die Zeitenwende verändert Deutschlands Sicherheitspolitik, aber der Antimilitarismus bleibt.","Deutschlands Nachkriegskultur macht es schwer, das 2%-Ziel der NATO zu erfüllen."],"correctAnswer":"Deutschlands langes Zögern beim NATO-2%-Ziel spiegelt einen fundamentalen kulturellen Widerspruch wider: Die Nachkriegskultur des Landes ist tief antimilitaristisch geprägt — durch die NS-Vergangenheit, durch die Friedensbewegung der 1980er und durch die Überzeugung, dass wirtschaftliche Einbindung sicherer ist als Rüstung. Die Zeitenwende hat diesen kulturellen Grundkonsens unter Druck gesetzt, aber nicht aufgelöst."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Finanzkrise hat den Konsens unter Druck gesetzt, aber nicht ___.","options":["aufgelöst","beseitigt","zerstört","überwunden"],"correctAnswer":"aufgelöst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The new competition puts the business model under pressure but does not dissolve it","wordBankItems":["Die","neue","Konkurrenz","setzt","das","Geschäftsmodell","unter","Druck",",","löst","es","aber","nicht","auf","."],"correctAnswer":"Die neue Konkurrenz setzt das Geschäftsmodell unter Druck , löst es aber nicht auf ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Geprägt'' means?","options":["stamped/shaped","marked","influenced","formed"],"correctAnswer":"stamped/shaped"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000031d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss human rights and international justice at B2","Use Menschenrechte vocabulary","Talk about the UN system, ICC, and universal human rights vs. cultural relativism"],"explanation":{"intro":"Human rights and international justice vocabulary covers the UN system, ICC, and the universalism vs. cultural relativism debate at B2.","culturalNote":"Menschenrechte und internationale Justiz: Key: UDHR (Universal Declaration of Human Rights — 1948). ECHR (European Convention on Human Rights — Council of Europe — European Court of Human Rights — Strasbourg). ICC (International Criminal Court — Rome Statute 1998 — Germany founding member — jurisdiction over genocide, war crimes, crimes against humanity, aggression). UN system: UNHCR, OHCHR, Human Rights Council. Key debate: Universalismus vs. Kulturrelativismus (universalism vs. cultural relativism — Singapore School — ''Asian values'' — sovereignty argument vs. universal standards). R2P (Responsibility to Protect — 2005 — obligation to protect civilians — Libya intervention — debate over abuse). Transitional Justice (Übergangsjustiz — Truth and Reconciliation, criminal prosecution — South Africa vs. Nuremberg models). Key Germany: Weltrechtsprinzip (universal jurisdiction — Germany prosecutes war crimes regardless of where committed — Syria, Rwanda). Syrische Sicherheitsdienste vor deutschen Gerichten."},"examples":[{"german":"Der Universalismus der Menschenrechte steht in einem ungelösten Spannungsverhältnis zum Souveränitätsprinzip: Die AEMR von 1948 kodifiziert Rechte, die allen Menschen ungeachtet ihrer Staatsbürgerschaft zustehen — aber ihre Durchsetzung bleibt weitgehend nationalstaatlicher Souveränität überlassen. Der Internationale Strafgerichtshof ist der institutionelle Versuch, diese Lücke zu schließen — mit begrenzten Mitteln und selektiver Praxis.","english":"The universalism of human rights stands in an unresolved tension with the sovereignty principle: the UDHR of 1948 codifies rights that belong to all people regardless of their citizenship — but their enforcement remains largely left to national state sovereignty. The International Criminal Court is the institutional attempt to close this gap — with limited means and selective practice."},{"german":"Das Weltrechtsprinzip ermöglicht Deutschland, schwerwiegende Menschenrechtsverletzungen auch ohne territorialen Bezug zu verfolgen: Wenn ein syrischer Geheimdienstoffizier nach Deutschland kommt, kann er wegen Verbrechen gegen die Menschlichkeit vor einem deutschen Gericht angeklagt werden, auch wenn die Taten in Syrien begangen wurden. Dieses Prinzip repräsentiert den Anspruch, dass bestimmte Verbrechen so schwerwiegend sind, dass sie kein Zufluchtort entgehen darf.","english":"The principle of universal jurisdiction enables Germany to prosecute serious human rights violations even without territorial connection: when a Syrian secret service officer comes to Germany, he can be prosecuted before a German court for crimes against humanity, even if the acts were committed in Syria. This principle represents the claim that certain crimes are so serious that no place of refuge may escape them."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the ICC, universal jurisdiction, and the tension between human rights universalism and state sovereignty at B2."}}',
'{"items":[{"word":"das Weltrechtsprinzip","translation":"principle of universal jurisdiction","pronunciation":"dahs VELT-rekhts-prin-tsi-p","example":"Weltrechtsprinzip anwenden."},{"word":"die Durchsetzung","translation":"enforcement","pronunciation":"dee DOORKH-zet-soong","example":"Durchsetzung von Rechten."},{"word":"der Zufluchtort","translation":"place of refuge","pronunciation":"dayr TSOO-flookht-ort","example":"Kein Zufluchtort."},{"word":"kodifizieren","translation":"to codify","pronunciation":"ko-di-fi-ZEE-ren","example":"Rechte kodifizieren."},{"word":"ungeachtet","translation":"regardless of","pronunciation":"oon-geh-AKH-tet","example":"Ungeachtet der Herkunft."},{"word":"die Übergangsjustiz","translation":"transitional justice","pronunciation":"dee Ü-ber-gangs-yoos-tits","example":"Übergangsjustizmodelle."}]}',
'{"title":"Etwas bleibt X überlassen — something remains left to X","pattern":"etwas bleibt X überlassen = something remains left to X (überlassen = to leave to, entrust to — passive/adjective: etwas ist X überlassen = something is left to X; bleibt = remains — marks continuity of the state)","explanation":"Überlassen = to leave to, hand over (jdm. etwas überlassen = to leave something to someone). Bleibt X überlassen = remains left to X (the state continues — nothing has changed this). Die Durchsetzung bleibt nationalstaatlicher Souveränität überlassen = enforcement remains left to national state sovereignty (i.e., no international enforcement body changes this). Marks that a gap remains — something is not addressed by the international system and falls back to states. Compare: liegt bei X (lies with X — who is responsible), obliegt X (falls to X — obligation sense), kommt X zu (falls to X — entitlement), verbleibt bei X (remains with X — more legal/procedural).","examples":[{"sentence":"Die Umsetzung der Richtlinie bleibt den Mitgliedstaaten überlassen.","translation":"The implementation of the directive remains left to the member states."},{"sentence":"Die Entscheidung bleibt dem Gericht überlassen.","translation":"The decision remains left to the court."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ungeachtet'' means?","options":["regardless of","despite","notwithstanding","irrespective of"],"correctAnswer":"regardless of"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The universalism of human rights stands in an unresolved tension with the sovereignty principle: the UDHR of 1948 codifies rights that belong to all people regardless of their citizenship — but their enforcement remains largely left to national state sovereignty. The International Criminal Court is the institutional attempt to close this gap — with limited means and selective practice.","options":["Der Universalismus der Menschenrechte steht in einem ungelösten Spannungsverhältnis zum Souveränitätsprinzip: Die AEMR von 1948 kodifiziert Rechte, die allen Menschen ungeachtet ihrer Staatsbürgerschaft zustehen — aber ihre Durchsetzung bleibt weitgehend nationalstaatlicher Souveränität überlassen. Der Internationale Strafgerichtshof ist der institutionelle Versuch, diese Lücke zu schließen — mit begrenzten Mitteln und selektiver Praxis.","Menschenrechte gelten für alle Menschen, aber Staaten können sie trotzdem verletzen.","Ohne Durchsetzungsmechanismus bleiben Menschenrechte nur auf dem Papier.","Der ICC versucht, internationale Strafgerichtsbarkeit für Menschenrechtsverletzungen zu schaffen."],"correctAnswer":"Der Universalismus der Menschenrechte steht in einem ungelösten Spannungsverhältnis zum Souveränitätsprinzip: Die AEMR von 1948 kodifiziert Rechte, die allen Menschen ungeachtet ihrer Staatsbürgerschaft zustehen — aber ihre Durchsetzung bleibt weitgehend nationalstaatlicher Souveränität überlassen. Der Internationale Strafgerichtshof ist der institutionelle Versuch, diese Lücke zu schließen — mit begrenzten Mitteln und selektiver Praxis."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Umsetzung der Richtlinie bleibt den Mitgliedstaaten ___.","options":["überlassen","anheimgestellt","offen","aufgegeben"],"correctAnswer":"überlassen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The decision remains left to the court","wordBankItems":["Die","Entscheidung","bleibt","dem","Gericht","überlassen","."],"correctAnswer":"Die Entscheidung bleibt dem Gericht überlassen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kodifizieren'' means?","options":["to codify","to enshrine","to formalise","to legislate"],"correctAnswer":"to codify"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000031e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss development policy and global justice at B2","Use Entwicklungspolitik vocabulary","Talk about ODA, debt relief, and the global justice debate"],"explanation":{"intro":"Development policy vocabulary covers ODA, debt relief, and the global justice debate at B2.","culturalNote":"Entwicklungspolitik und globale Gerechtigkeit: Germany: BMZ (Bundesministerium für wirtschaftliche Zusammenarbeit und Entwicklung — Federal Ministry for Economic Cooperation — 0.83% GNI development aid 2022 — above UN 0.7% target). GIZ (Deutsche Gesellschaft für Internationale Zusammenarbeit — development agency). KfW (development bank). Key: ODA (Official Development Assistance). Key debate: Aid vs. Trade (''trade not aid'' — Dambisa Moyo Dead Aid 2009). Schuldenerlass (debt relief — HIPC initiative). Conditionality (Konditionalität — IMF/World Bank structural adjustment — controversial). Sustainable Development Goals (SDGs — 17 goals by 2030 — UN 2015). Key: Global tax justice (Steuergerechtigkeit — BEPS — base erosion and profit shifting — tax havens undermine development). Climate finance (Klimafinanzierung — global North obligations to South). Reparations (Namibia — Herero und Nama genocide — Germany paid reparations 2021 — €1.1bn). Decolonisation (Dekolonisierung — academic and political discourse)."},"examples":[{"german":"Die Wirksamkeitsdebatte in der Entwicklungspolitik hat das Feld grundlegend verändert: Die Kritik Dambisa Moyos (''Dead Aid'' 2009) und die Evidenzbasierung der Wirkungsforschung (RCTs — Randomisierte Kontrollstudien — Esther Duflo, Michael Kremer, Abhijit Banerjee — Nobelpreis 2019) haben gezeigt, dass Entwicklungshilfe nicht per se wirksam ist — sondern dass Wirksamkeit von Zielgenauigkeit, Kontext und Anreizstrukturen abhängt.","english":"The effectiveness debate in development policy has fundamentally changed the field: the critique of Dambisa Moyo (''Dead Aid'' 2009) and the evidence-basing of impact research (RCTs — randomised controlled trials — Esther Duflo, Michael Kremer, Abhijit Banerjee — Nobel Prize 2019) have shown that development aid is not effective per se — but that effectiveness depends on targeting, context, and incentive structures."},{"german":"Das Konzept der globalen Steuergerechtigkeit verbindet Entwicklungspolitik mit Finanzpolitik: Gewinnverschiebung durch multinationale Konzerne in Niedrigsteuergebiete entzieht Entwicklungsländern Steuereinnahmen, die für Bildung, Gesundheit und Infrastruktur dringend benötigt werden. Die OECD-BEPS-Initiative und die Mindeststeuervereinbarung (15% globale Mindestkörperschaftssteuer 2021) sind erste Antworten auf dieses strukturelle Problem.","english":"The concept of global tax justice connects development policy with fiscal policy: profit shifting by multinational corporations to low-tax jurisdictions deprives developing countries of tax revenues that are urgently needed for education, health, and infrastructure. The OECD BEPS initiative and the minimum tax agreement (15% global minimum corporate tax 2021) are the first responses to this structural problem."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss development aid effectiveness, Dead Aid critique, and global tax justice at B2."}}',
'{"items":[{"word":"die Wirksamkeit","translation":"effectiveness","pronunciation":"dee VIRK-zahm-kyt","example":"Wirksamkeit der Entwicklungshilfe."},{"word":"die Zielgenauigkeit","translation":"targeting","pronunciation":"dee TSEEL-geh-noy-ikh-kyt","example":"Zielgenauigkeit verbessern."},{"word":"die Gewinnverschiebung","translation":"profit shifting","pronunciation":"dee geh-VIN-fer-shee-boong","example":"Steuerliche Gewinnverschiebung."},{"word":"entziehen","translation":"to deprive of","pronunciation":"ent-TSEE-en","example":"Steuereinnahmen entziehen."},{"word":"die Konditionalität","translation":"conditionality","pronunciation":"dee kon-di-tsyo-na-li-TÄT","example":"IWF-Konditionalität."},{"word":"per se","translation":"per se/in itself","pronunciation":"per ZEH","example":"Nicht per se wirksam."}]}',
'{"title":"Etwas zeigt, dass X nicht per se Y ist — something shows that X is not Y per se","pattern":"etwas zeigt, dass X nicht per se Y ist = something shows that X is not Y per se (per se = in itself, by nature; nicht per se = not inherently/not automatically; marks that X has no intrinsic connection to Y — outcome depends on conditions)","explanation":"Per se = in itself, by its very nature (Latin: through itself). Nicht per se = not inherently, not automatically. Forschung zeigt, dass Hilfe nicht per se wirksam ist = research shows that aid is not effective per se. The pattern marks a refutation of an assumed automatic connection: X is not inherently Y — the result depends on conditions (context, targeting, design). Compare: nicht zwangsläufig (not necessarily — more probabilistic), nicht automatisch (not automatically — temporal sense), nicht in jedem Fall (not in every case — more case-based), es kommt darauf an (it depends — more conditional, less analytical).","examples":[{"sentence":"Wirtschaftswachstum ist nicht per se gut für Arme.","translation":"Economic growth is not good for the poor per se."},{"sentence":"Transparenz ist nicht per se ausreichend für Vertrauen.","translation":"Transparency is not sufficient for trust per se."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Wirksamkeit'' means?","options":["effectiveness","efficacy","efficiency","impact"],"correctAnswer":"effectiveness"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The effectiveness debate in development policy has fundamentally changed the field: the critique of Dambisa Moyo (''Dead Aid'' 2009) and the evidence-basing of impact research (RCTs — randomised controlled trials — Esther Duflo, Michael Kremer, Abhijit Banerjee — Nobel Prize 2019) have shown that development aid is not effective per se — but that effectiveness depends on targeting, context, and incentive structures.","options":["Die Wirksamkeitsdebatte in der Entwicklungspolitik hat das Feld grundlegend verändert: Die Kritik Dambisa Moyos (''Dead Aid'' 2009) und die Evidenzbasierung der Wirkungsforschung (RCTs — Randomisierte Kontrollstudien — Esther Duflo, Michael Kremer, Abhijit Banerjee — Nobelpreis 2019) haben gezeigt, dass Entwicklungshilfe nicht per se wirksam ist — sondern dass Wirksamkeit von Zielgenauigkeit, Kontext und Anreizstrukturen abhängt.","Entwicklungshilfe funktioniert nur unter bestimmten Bedingungen — nicht immer.","RCTs haben gezeigt, dass manche Hilfsprogramme wirksam sind und andere nicht.","Dead Aid kritisiert, dass Entwicklungshilfe Abhängigkeit schafft statt Wachstum."],"correctAnswer":"Die Wirksamkeitsdebatte in der Entwicklungspolitik hat das Feld grundlegend verändert: Die Kritik Dambisa Moyos (''Dead Aid'' 2009) und die Evidenzbasierung der Wirkungsforschung (RCTs — Randomisierte Kontrollstudien — Esther Duflo, Michael Kremer, Abhijit Banerjee — Nobelpreis 2019) haben gezeigt, dass Entwicklungshilfe nicht per se wirksam ist — sondern dass Wirksamkeit von Zielgenauigkeit, Kontext und Anreizstrukturen abhängt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wirtschaftswachstum ist nicht per se gut für ___.","options":["Arme","alle","Entwicklung","Wohlstand"],"correctAnswer":"Arme"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Transparency is not sufficient for trust per se","wordBankItems":["Transparenz","ist","nicht","per","se","ausreichend","für","Vertrauen","."],"correctAnswer":"Transparenz ist nicht per se ausreichend für Vertrauen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Gewinnverschiebung'' means?","options":["profit shifting","profit transfer","earnings displacement","income shifting"],"correctAnswer":"profit shifting"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000031f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital democracy and e-government at B2","Use Digitale Demokratie vocabulary","Talk about e-voting, online participation, and Germany''s digital governance challenges"],"explanation":{"intro":"Digital democracy vocabulary covers e-government, digital participation, and Germany''s notoriously slow digitisation of public administration at B2.","culturalNote":"Digitale Demokratie und E-Government: Germany: Onlinezugangsgesetz (Online Access Act — OZG — 2017 — 575 government services online by 2022 — largely missed). Key challenge: Germany ranked 18th in UN e-government ranking 2022 — below expectations for Europe''s largest economy. Digitalstrategie (Federal Digital Strategy 2022). Servicestandard (service standard for digital government). Key: Govtech. ELSTER (online tax filing — success). Key debate: E-Voting (electronic voting — Germany rejected after BVerfG 2009 ruled it unconstitutional due to lack of public verifiability — reverse later). Digital participation (Bürgerbeteiligung digital). Algorithmic decision-making in government (Verwaltungsautomation — AZRG). Datenschutz (data protection — tension with e-government efficiency). Open Government Partnership. Hackathons (Bundesregierung Hackathons). Transparenzregister. GOVDATA (open data)."},"examples":[{"german":"Die digitale Transformation der öffentlichen Verwaltung in Deutschland hinkt dem privaten Sektor um Jahre hinterher: Während kommerzielle Dienste nahtlose digitale Erlebnisse liefern, erfordern viele Behördengänge weiterhin persönliche Anwesenheit, physische Unterschriften und Papierformulare — ein Verwaltungsparadox in einem der wohlhabendsten Länder der Welt. Die Gründe sind strukturell: Föderalismus fragmentiert Zuständigkeiten, Datenschutz bremst Datenaustausch und Investitionsrückstände sind nicht in einer Legislaturperiode aufzuholen.","english":"The digital transformation of public administration in Germany lags behind the private sector by years: while commercial services deliver seamless digital experiences, many administrative processes still require personal presence, physical signatures, and paper forms — an administrative paradox in one of the world''s wealthiest countries. The reasons are structural: federalism fragments responsibilities, data protection brakes data exchange, and investment backlogs cannot be caught up in a single legislative period."},{"german":"Das Bundesverfassungsgericht hat 2009 elektronische Wahlmaschinen für verfassungswidrig erklärt, weil sie dem Grundsatz öffentlicher Wahl widersprechen: Wahlen müssen öffentlich überprüfbar sein — also von jedem Bürger, ohne Spezialkenntnisse. Computersysteme erfüllen diese Anforderung nicht: Softwarefehler und Manipulationen sind für durchschnittliche Bürger nicht erkennbar. Das Urteil markiert eine verfassungsrechtliche Grenze des technologischen Fortschritts in der Demokratie.","english":"The Federal Constitutional Court declared electronic voting machines unconstitutional in 2009 because they contradict the principle of public elections: elections must be publicly verifiable — that is, by every citizen, without specialist knowledge. Computer systems do not meet this requirement: software errors and manipulations are not recognisable for average citizens. The ruling marks a constitutional limit of technological progress in democracy."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s e-government lag, the Constitutional Court''s e-voting ruling, and digital transformation barriers at B2."}}',
'{"items":[{"word":"hinterherhinken","translation":"to lag behind","pronunciation":"hin-ter-her-HIN-ken","example":"Um Jahre hinterherhinken."},{"word":"nahtlos","translation":"seamless","pronunciation":"NAHT-lohs","example":"Nahtloses Erlebnis."},{"word":"die Zuständigkeit","translation":"responsibility/jurisdiction","pronunciation":"dee TSOO-shten-dikh-kyt","example":"Föderale Zuständigkeiten."},{"word":"der Investitionsrückstand","translation":"investment backlog","pronunciation":"dayr in-ves-ti-TSYOHNS-rük-shtant","example":"Investitionsrückstände aufholen."},{"word":"die Überprüfbarkeit","translation":"verifiability","pronunciation":"dee ü-ber-PRÜF-bar-kyt","example":"Öffentliche Überprüfbarkeit."},{"word":"fragmentieren","translation":"to fragment","pronunciation":"frag-men-TEE-ren","example":"Zuständigkeiten fragmentieren."}]}',
'{"title":"X sind in Y nicht aufzuholen — X cannot be caught up in Y (in a single...)","pattern":"X sind in Y nicht aufzuholen = X cannot be caught up in Y (aufholen = to catch up; nicht aufzuholen = cannot be caught up — modal passive with sein + zu + infinitive, negated; in einer Legislaturperiode = in a single legislative period)","explanation":"Aufholen = to catch up (aus/auf = up + holen = to fetch; aufholen = to close a gap). Nicht aufzuholen = cannot be caught up (sein + zu + infinitive, negated — same modal passive as ''nicht zu reduzieren'' — marks impossibility). In einer Legislaturperiode = in a single legislative period (four-year span — marks the time constraint). Investitionsrückstände sind in einer Legislaturperiode nicht aufzuholen = investment backlogs cannot be caught up in a single legislative period. Marks that the magnitude of a backlog or gap exceeds what any realistic short-term response can address. Compare: nicht so schnell zu beheben (not to be fixed so quickly — more informal), nicht innerhalb kurzer Zeit zu beseitigen (not to be eliminated in a short time — more wordy), braucht Jahrzehnte (takes decades — more time-framing), zu groß für X (too large for X — simpler statement of scale).","examples":[{"sentence":"Der Wissensvorsprung ist in wenigen Jahren nicht aufzuholen.","translation":"The knowledge lead cannot be caught up in a few years."},{"sentence":"Die Infrastrukturlücke ist in einer Amtszeit nicht aufzuholen.","translation":"The infrastructure gap cannot be caught up in one term of office."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Nahtlos'' means?","options":["seamless","smooth","uninterrupted","continuous"],"correctAnswer":"seamless"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The digital transformation of public administration in Germany lags behind the private sector by years: while commercial services deliver seamless digital experiences, many administrative processes still require personal presence, physical signatures, and paper forms — an administrative paradox in one of the world''s wealthiest countries. The reasons are structural: federalism fragments responsibilities, data protection brakes data exchange, and investment backlogs cannot be caught up in a single legislative period.","options":["Die digitale Transformation der öffentlichen Verwaltung in Deutschland hinkt dem privaten Sektor um Jahre hinterher: Während kommerzielle Dienste nahtlose digitale Erlebnisse liefern, erfordern viele Behördengänge weiterhin persönliche Anwesenheit, physische Unterschriften und Papierformulare — ein Verwaltungsparadox in einem der wohlhabendsten Länder der Welt. Die Gründe sind strukturell: Föderalismus fragmentiert Zuständigkeiten, Datenschutz bremst Datenaustausch und Investitionsrückstände sind nicht in einer Legislaturperiode aufzuholen.","Deutschland digitalisiert langsam, weil Datenschutz und Bürokratie es bremsen.","Online-Dienste der Verwaltung sind schlechter als kommerzielle Dienste — das ist ein Paradox.","E-Government in Deutschland scheitert an Föderalismus, Datenschutz und fehlenden Investitionen."],"correctAnswer":"Die digitale Transformation der öffentlichen Verwaltung in Deutschland hinkt dem privaten Sektor um Jahre hinterher: Während kommerzielle Dienste nahtlose digitale Erlebnisse liefern, erfordern viele Behördengänge weiterhin persönliche Anwesenheit, physische Unterschriften und Papierformulare — ein Verwaltungsparadox in einem der wohlhabendsten Länder der Welt. Die Gründe sind strukturell: Föderalismus fragmentiert Zuständigkeiten, Datenschutz bremst Datenaustausch und Investitionsrückstände sind nicht in einer Legislaturperiode aufzuholen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Wissensvorsprung ist in wenigen Jahren nicht ___.","options":["aufzuholen","einzuholen","aufholbar","zu schließen"],"correctAnswer":"aufzuholen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The infrastructure gap cannot be caught up in one term of office","wordBankItems":["Die","Infrastrukturlücke","ist","in","einer","Amtszeit","nicht","aufzuholen","."],"correctAnswer":"Die Infrastrukturlücke ist in einer Amtszeit nicht aufzuholen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Überprüfbarkeit'' means?","options":["verifiability","accountability","transparency","scrutiny"],"correctAnswer":"verifiability"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

-- Lesson 800: MILESTONE — xp:200, coins:100
INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000320',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the future of democracy at B2","Use Zukunft der Demokratie vocabulary","Talk about democratic backsliding, populism, and democratic renewal"],"explanation":{"intro":"The future of democracy vocabulary covers democratic backsliding, populism, and debates about democratic renewal at B2 — completing the German B2 curriculum.","culturalNote":"Zukunft der Demokratie: Key: Democratic backsliding (Demokratieabbau — Hungary, Poland, Turkey — how democracies die from within — Levitsky/Ziblatt). Populismus (populism — defining feature: ''pure people'' vs. ''corrupt elite'' — Cas Mudde). AfD, RN, FPÖ in Europe. Key: Wahlautoritarismus (electoral authoritarianism — Levitsky/Way — competitive but not fair elections). Technokratie (technocracy — governance by experts — limits democratic responsiveness). Epistokratie (epistocracy — Jason Brennan Against Democracy — weighted voting by knowledge). Liquid Democracy (continuous participatory democracy via delegation). Key resilience: judicial independence, press freedom, civic society. Germany: Wehrhafte Demokratie (militant democracy — concept by Karl Loewenstein 1937 — democracy that defends itself — Parteiverbot — art. 21 GG). Verfassungsschutz (domestic intelligence — monitoring of extremists). NPD-Verbot (failed 2003, 2017 — lack of substantiality). AfD Verfassungsschutzbeobachtung (AFD under observation). Key: What makes democracy durable? Institutions, norms, civic culture — Robert Dahl''s polyarchy."},"examples":[{"german":"Die resiliente Demokratie braucht mehr als Institutionen — sie braucht normative Kultur: Die Institutionen des Rechtsstaats, der Gewaltenteilung und des Wahlrechts schützen Demokratie, aber ihre Wirksamkeit hängt davon ab, dass politische Akteure und Bürgerinnen informelle Normen der Mäßigung, des gegenseitigen Respekts und der institutionellen Loyalität einhalten. Steven Levitsky und Daniel Ziblatt nennen das ''mutual toleration'' und ''institutional forbearance'' — Normen, die Institutionen nicht erzwingen können.","english":"Resilient democracy needs more than institutions — it needs normative culture: the institutions of the rule of law, separation of powers, and electoral rights protect democracy, but their effectiveness depends on political actors and citizens adhering to informal norms of moderation, mutual respect, and institutional loyalty. Steven Levitsky and Daniel Ziblatt call this ''mutual toleration'' and ''institutional forbearance'' — norms that institutions cannot enforce."},{"german":"Demokratischer Rückfall vollzieht sich selten durch Militärputsche, sondern durch legale Erosion: Gewählte Führer nutzen demokratische Instrumente — Gesetze, Wahlen, Gerichte — um demokratische Institutionen schrittweise auszuhöhlen, die Presse einzuschränken, die Justizunabhängigkeit zu untergraben und die Zivilgesellschaft zu schwächen. Diese schleichende Form des Demokratieabbaus ist schwerer zu erkennen und zu bekämpfen als ein offener Staatsstreich — weil jeder einzelne Schritt eine legale Erklärung hat.","english":"Democratic backsliding rarely occurs through military coups, but through legal erosion: elected leaders use democratic instruments — laws, elections, courts — to gradually hollow out democratic institutions, restrict the press, undermine judicial independence, and weaken civil society. This creeping form of democratic decay is harder to recognise and combat than an open coup — because each individual step has a legal explanation."}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss democratic backsliding, militant democracy, and the normative prerequisites for resilient democracy at B2 — completing German B2."}}',
'{"items":[{"word":"das Demokratieabbau","translation":"democratic backsliding","pronunciation":"dahs deh-mo-kra-TEE-ab-bow","example":"Schleichender Demokratieabbau."},{"word":"die Mäßigung","translation":"moderation","pronunciation":"dee MÄ-si-goong","example":"Politische Mäßigung."},{"word":"aushöhlen","translation":"to hollow out","pronunciation":"OWS-hö-len","example":"Institutionen aushöhlen."},{"word":"schleichend","translation":"creeping/insidious","pronunciation":"SHLY-khend","example":"Schleichende Erosion."},{"word":"die Wehrhafte Demokratie","translation":"militant democracy","pronunciation":"dee VEHR-haf-teh deh-mo-kra-TEE","example":"Konzept der wehrhaften Demokratie."},{"word":"die institutionelle Loyalität","translation":"institutional loyalty","pronunciation":"dee in-sti-too-tsyo-NEL-eh lo-ya-li-TÄT","example":"Institutionelle Loyalität wahren."}]}',
'{"title":"X vollzieht sich selten durch Y, sondern durch Z — X rarely occurs through Y but through Z","pattern":"X vollzieht sich selten durch Y, sondern durch Z = X rarely occurs through Y, but through Z (sich vollziehen durch = to come about through; selten = rarely — marks that the common assumption (through Y) is wrong, and the actual mechanism (through Z) is different and often more subtle)","explanation":"Sich vollziehen durch = to come about through, unfold through (vollziehen = to carry out; reflexive = to unfold on its own; durch = through the mechanism of). Selten = rarely (marks that Y is not impossible but is the exception, not the rule). Sondern durch Z = but through Z (correction of the assumption). Demokratischer Rückfall vollzieht sich selten durch Militärputsche, sondern durch legale Erosion = democratic backsliding rarely occurs through military coups, but through legal erosion. The pattern corrects a common false mental model with the actual, more complex mechanism. Compare: nicht X, sondern Y (not X but Y — harder negation without the ''rarely''), entgegen der Erwartung (contrary to expectation — more about surprise), wider Erwarten (against expectation — similar), in Wirklichkeit (in reality — softer correction).","examples":[{"sentence":"Vertrauen geht selten durch Betrug verloren, sondern durch kleine Enttäuschungen.","translation":"Trust is rarely lost through fraud, but through small disappointments."},{"sentence":"Innovation vollzieht sich selten durch Durchbrüche, sondern durch kumulative Verbesserungen.","translation":"Innovation rarely occurs through breakthroughs, but through cumulative improvements."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Aushöhlen'' means?","options":["to hollow out","to undermine","to erode","to weaken"],"correctAnswer":"to hollow out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Democratic backsliding rarely occurs through military coups, but through legal erosion: elected leaders use democratic instruments — laws, elections, courts — to gradually hollow out democratic institutions, restrict the press, undermine judicial independence, and weaken civil society. This creeping form of democratic decay is harder to recognise and combat than an open coup — because each individual step has a legal explanation.","options":["Demokratischer Rückfall vollzieht sich selten durch Militärputsche, sondern durch legale Erosion: Gewählte Führer nutzen demokratische Instrumente — Gesetze, Wahlen, Gerichte — um demokratische Institutionen schrittweise auszuhöhlen, die Presse einzuschränken, die Justizunabhängigkeit zu untergraben und die Zivilgesellschaft zu schwächen. Diese schleichende Form des Demokratieabbaus ist schwerer zu erkennen und zu bekämpfen als ein offener Staatsstreich — weil jeder einzelne Schritt eine legale Erklärung hat.","Demokratie stirbt nicht durch Militärputsche, sondern durch die allmähliche Erosion ihrer Institutionen.","Gewählte Autokraten höhlen Demokratie von innen aus, indem sie ihre Instrumente missbrauchen.","Demokratischer Abbau ist schwer zu erkennen, weil er legal und schrittweise erfolgt."],"correctAnswer":"Demokratischer Rückfall vollzieht sich selten durch Militärputsche, sondern durch legale Erosion: Gewählte Führer nutzen demokratische Instrumente — Gesetze, Wahlen, Gerichte — um demokratische Institutionen schrittweise auszuhöhlen, die Presse einzuschränken, die Justizunabhängigkeit zu untergraben und die Zivilgesellschaft zu schwächen. Diese schleichende Form des Demokratieabbaus ist schwerer zu erkennen und zu bekämpfen als ein offener Staatsstreich — weil jeder einzelne Schritt eine legale Erklärung hat."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Innovation vollzieht sich selten durch Durchbrüche, sondern durch kumulative ___.","options":["Verbesserungen","Schritte","Entwicklungen","Fortschritte"],"correctAnswer":"Verbesserungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust is rarely lost through fraud but through small disappointments","wordBankItems":["Vertrauen","geht","selten","durch","Betrug","verloren",",","sondern","durch","kleine","Enttäuschungen","."],"correctAnswer":"Vertrauen geht selten durch Betrug verloren , sondern durch kleine Enttäuschungen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schleichend'' means?","options":["creeping/insidious","gradual","slow","progressive"],"correctAnswer":"creeping/insidious"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

